//===- forms.cc -------------------------------------------------*- C++ -*-===//
//
// bf16 MAC forms capture kernel (GENERATED by tools/gen_mac_bf16_forms.py).
// Runs every form in FORMS over each of T tiles of one chunk; the layout of the
// chunk is A[T*32] bf16, B[T*32] bf16, C0[T*16] fp32, C1[T*16] fp32.
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

#include <aie_api/aie.hpp>

#define T 16
#define NFORMS 23

extern "C" {

void mac_forms(bfloat16 *restrict in, float *restrict out) {
  bfloat16 *inA = in;
  bfloat16 *inB = in + T * 32;
  float *inC0 = (float *)(in + 2 * T * 32);
  float *inC1 = inC0 + T * 16;
  event0();
  for (int n = 0; n < T; n++) {
    aie::vector<bfloat16, 32> a = aie::load_v<32>(inA + n * 32);
    aie::vector<bfloat16, 32> b = aie::load_v<32>(inB + n * 32);
    aie::accum<accfloat, 16> c0;
    c0.from_vector(aie::load_v<16>(inC0 + n * 16));
    aie::accum<accfloat, 16> c1;
    c1.from_vector(aie::load_v<16>(inC1 + n * 16));
    float *o = out + n * NFORMS * 16;
    { aie::accum<accfloat, 16> r = ::mul_4x8_8x4(a, b); aie::store_v(o + 0 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negmul_4x8_8x4(a, b); aie::store_v(o + 1 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mac_4x8_8x4(a, b, c0); aie::store_v(o + 2 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::msc_4x8_8x4(a, b, c0); aie::store_v(o + 3 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mac_4x8_8x4_conf(a, b, c0, 0, 0, 1); aie::store_v(o + 4 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mac_4x8_8x4_conf(a, b, c0, 0, 1, 0); aie::store_v(o + 5 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mac_4x8_8x4_conf(a, b, c0, 0, 1, 1); aie::store_v(o + 6 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::msc_4x8_8x4_conf(a, b, c0, 0, 1, 0); aie::store_v(o + 7 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::msc_4x8_8x4_conf(a, b, c0, 0, 0, 1); aie::store_v(o + 8 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::msc_4x8_8x4_conf(a, b, c0, 0, 1, 1); aie::store_v(o + 9 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mul_4x8_8x4_conf(a, b, 1); aie::store_v(o + 10 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negmul_4x8_8x4_conf(a, b, 1); aie::store_v(o + 11 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mac_4x8_8x4_conf(a, b, c0, 1, 0, 0); aie::store_v(o + 12 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::addmac_4x8_8x4(a, b, c0, c1); aie::store_v(o + 13 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::addmsc_4x8_8x4(a, b, c0, c1); aie::store_v(o + 14 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::addmac_4x8_8x4_conf(a, b, c0, c1, 0, 0, 0, 1); aie::store_v(o + 15 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::addmac_4x8_8x4_conf(a, b, c0, c1, 0, 0, 1, 0); aie::store_v(o + 16 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::addmac_4x8_8x4_conf(a, b, c0, c1, 0, 1, 0, 0); aie::store_v(o + 17 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::addmsc_4x8_8x4_conf(a, b, c0, c1, 0, 0, 0, 1); aie::store_v(o + 18 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mul_elem_16_2(a, b); aie::store_v(o + 19 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::negmul_elem_16_2(a, b); aie::store_v(o + 20 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::mac_elem_16_2(a, b, c0); aie::store_v(o + 21 * 16, r.to_vector<float>()); }
    { aie::accum<accfloat, 16> r = ::msc_elem_16_2(a, b, c0); aie::store_v(o + 22 * 16, r.to_vector<float>()); }
  }
  event1();
}

} // extern "C"
